import{_ as r,c as i,o as s,j as a,a8 as t,t as n,a as v}from"./chunks/framework.jsZJWZJf.js";const _=JSON.parse('{"title":"为什么学生不喜欢上学？：认知心理学家解开大脑学习的运作结构，如何更有效地学习与思考 - 读书笔记","description":"","frontmatter":{"title":"为什么学生不喜欢上学？：认知心理学家解开大脑学习的运作结构，如何更有效地学习与思考 - 读书笔记","outline":[2,2],"finishedDate":"2025-01-05"},"headers":[],"relativePath":"blog/read/books/为什么学生不喜欢学习.md","filePath":"blog/read/books/为什么学生不喜欢学习.md","lastUpdated":1795017144000}'),p={name:"blog/read/books/为什么学生不喜欢学习.md"},c={class:"social-psychology-notes"},l={class:"reading-book","aria-label":"书籍信息"},o={class:"reading-book-info"},u={class:"reading-metadata"},b=["datetime"];function x(e,d,g,h,k,q){return s(),i("div",null,[a("div",c,[d[8]||(d[8]=a("header",{class:"reading-header"},[a("h1",null,"为什么学生不喜欢上学？：认知心理学家解开大脑学习的运作结构，如何更有效地学习与思考"),a("p",{class:"reading-byline"},"作者：丹尼尔·T.威林厄姆"),a("div",{class:"reading-stats"},[a("span",null,"49 条摘抄"),a("span",null,"4 则随想"),a("span",null,"微信读书")])],-1)),a("section",l,[d[7]||(d[7]=a("div",{class:"reading-cover"},[a("img",{src:"https://cdn.weread.qq.com/weread/cover/67/cpplatform_41udcg8b6xhgmji7sr8rjg/t6_cpplatform_41udcg8b6xhgmji7sr8rjg1679975058.jpg",alt:"为什么学生不喜欢上学？：认知心理学家解开大脑学习的运作结构，如何更有效地学习与思考封面",width:"160",loading:"lazy"})],-1)),a("div",o,[d[4]||(d[4]=a("p",{class:"reading-book-title"},"书籍信息",-1)),a("dl",u,[d[1]||(d[1]=t("<div data-v-d5786234><dt data-v-d5786234>书名</dt><dd data-v-d5786234>为什么学生不喜欢上学？：认知心理学家解开大脑学习的运作结构，如何更有效地学习与思考</dd></div><div data-v-d5786234><dt data-v-d5786234>作者</dt><dd data-v-d5786234>丹尼尔·T.威林厄姆</dd></div><div data-v-d5786234><dt data-v-d5786234>出版社</dt><dd data-v-d5786234>中国青年出版社</dd></div><div data-v-d5786234><dt data-v-d5786234>出版时间</dt><dd data-v-d5786234>2023-01-01 00:00:00</dd></div>",4)),a("div",null,[d[0]||(d[0]=a("dt",null,"完读日期",-1)),a("dd",null,[a("time",{datetime:e.$frontmatter.finishedDate},n(e.$frontmatter.finishedDate),9,b)])]),d[2]||(d[2]=a("div",null,[a("dt",null,"ISBN"),a("dd",null,"9787515367088")],-1)),d[3]||(d[3]=a("div",null,[a("dt",null,"分类"),a("dd",null,"教育学习-教育")],-1))]),d[5]||(d[5]=a("a",{class:"reading-original-link",href:"https://weread.qq.com/web/reader/80232970813ab7b89g0141bc",target:"_blank",rel:"noopener noreferrer"},[v("在微信读书中打开 "),a("span",{"aria-hidden":"true"},"↗")],-1)),d[6]||(d[6]=a("details",{class:"reading-description"},[a("summary",null,"书籍简介"),a("p",null,"本书以“人类是如何思考和学习的”为线索，按章节依次阐述了大脑关于学习的10项基本运作原理，回答了诸如为何我们无须费力就能记住热播剧剧情却记不住知识等普遍学习困惑，揭示了故事、情感、记忆、背景知识、练习在构建知识和创造持久学习经验中的重要性，据此给出教育工作者提高学生的学习能力及精进教学技艺的方法建议。 作者的多个观点会颠覆你的固有认知，你将会重新认识并思考以下主题：“事实性知识优先于技能知识”“反复练习是精通任何脑力工作的开始”“因材施教是否有科学性证据支持”“智能可通过持续努力而改变掌握10大认知原则，就能掌握有效学习的诀窍，不是你不喜欢学习，原来是大脑喜欢这样学！")],-1))])]),d[9]||(d[9]=t('<h2 id="excerpts" tabindex="-1" data-v-d5786234>摘抄 <a class="header-anchor" href="#excerpts" aria-label="Permalink to “摘抄”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-001" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>001</span><div data-v-d5786234><p data-v-d5786234>如果你一遍又一遍地重复同样的需要思考的任务，它最终会变成自动完成；你的大脑会发生变化，这样你就能不假思索地完成任务。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-002" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>002</span><div data-v-d5786234><p data-v-d5786234>亚里士多德说：“从思考和学习中获得的乐趣将使我们思考和学习得更多</p></div></blockquote><h2 id="第2章-当标准化测试只需要事实时-教师如何教授学生所需要的技能" tabindex="-1" data-v-d5786234>第2章 当标准化测试只需要事实时，教师如何教授学生所需要的技能？ <a class="header-anchor" href="#第2章-当标准化测试只需要事实时-教师如何教授学生所需要的技能" aria-label="Permalink to “第2章 当标准化测试只需要事实时，教师如何教授学生所需要的技能？”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-003" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>003</span><div data-v-d5786234><p data-v-d5786234>背景知识的最后一个作用，即长期记忆中的事实性知识使人们更容易获得更多的事实性知识，这是值得深思的。这意味着你持有的信息量取决于你已经拥有的信息量</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-004" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>004</span><div data-v-d5786234><p data-v-d5786234>因为长期记忆能力强的人更容易学习，这种差距只会越来越大。我能赶上你的唯一办法就是确保我比你了解更多的事实性知识</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-005" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>005</span><div data-v-d5786234><p data-v-d5786234>应该教学生哪些知识”这个问题并不等同于“什么知识是重要的”，而是“你希望学生能够做什么”</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-006" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>006</span><div data-v-d5786234><p data-v-d5786234>认知科学得出了一个相当明显的结论，即学生必须学习反复出现的概念，即每个学科的通用概念</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-007" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>007</span><div data-v-d5786234><p data-v-d5786234>浅显的知识也胜过无知识</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-008" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>008</span><div data-v-d5786234><p data-v-d5786234>知识渊博固然好，但是我们不可能对所有的东西都有深刻认识，略知一二肯定比没有认识要好</p></div></blockquote><aside class="reading-thought" aria-label="个人随想" data-v-d5786234><div class="reading-thought-meta" data-v-d5786234><span data-v-d5786234>我的随想</span><time datetime="2024-12-10" data-v-d5786234>2024/12/10</time></div><p data-v-d5786234>广泛的阅读，保持对所有事物的新鲜感</p><blockquote class="reading-thought-source" data-v-d5786234><p class="reading-source-label" data-v-d5786234>对应原文</p><p data-v-d5786234>知识渊博固然好，但是我们不可能对所有的东西都有深刻认识，略知一二肯定比没有认识要好</p></blockquote></aside><blockquote class="reading-excerpt" id="excerpt-009" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>009</span><div data-v-d5786234><p data-v-d5786234>学生不能从阅读低于自己阅读水平的书中获得太多，而且每种阅读水平都存在有趣而迷人的书，所以为什么不把她推向适合她的书呢？</p></div></blockquote><h2 id="第3章-为什么学生记得住电视上的所有细节-却忘记我们教给他们的知识呢" tabindex="-1" data-v-d5786234>第3章 为什么学生记得住电视上的所有细节，却忘记我们教给他们的知识呢？ <a class="header-anchor" href="#第3章-为什么学生记得住电视上的所有细节-却忘记我们教给他们的知识呢" aria-label="Permalink to “第3章 为什么学生记得住电视上的所有细节，却忘记我们教给他们的知识呢？”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-010" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>010</span><div data-v-d5786234><p data-v-d5786234>重复是推动学习成功的另一个重要原因</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-011" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>011</span><div data-v-d5786234><p data-v-d5786234>学习与我无关的东西是一种价值，非常有趣，像追求一种美感。我并不是说谈论学生感兴趣的事情毫无意义。我的建议是，学生的兴趣不应该成为课程规划的主要动力。相反，它们可以被用来作为最初的触发点，帮助学生理解你想让他们思考的主要观点，而不是他们考虑这些观点的理由或动机</p></div></blockquote><h2 id="第4章-为什么学生很难理解抽象的概念" tabindex="-1" data-v-d5786234>第4章 为什么学生很难理解抽象的概念？ <a class="header-anchor" href="#第4章-为什么学生很难理解抽象的概念" aria-label="Permalink to “第4章 为什么学生很难理解抽象的概念？”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-012" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>012</span><div data-v-d5786234><p data-v-d5786234>问题的解决不是通过提供新的信息，而是通过整理我们一直知道的事情</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-013" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>013</span><div data-v-d5786234><p data-v-d5786234>理解新观点主要是将正确的旧观点输入工作记忆，然后重新排列它们——进行我们以前没有做过的比较，或者思考我们以前忽略的特征</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-014" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>014</span><div data-v-d5786234><p data-v-d5786234>塞尔想要论证的是，计算机可能会在没有真正理解自己在做什么的情况下表现出智能行为</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-015" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>015</span><div data-v-d5786234><p data-v-d5786234>我们可以将浅表知识与深层知识进行对比。知识渊博的学生对这门学科了解得更多，他们的知识碎片之间的联系也更为丰富。这类学生不仅理解部分，也理解整体。这种理解使学生在许多不同的背景下灵活地应用知识，以不同的方式谈论它，想象如果一个部分发生变化，整个系统将如何变化</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-016" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>016</span><div data-v-d5786234><p data-v-d5786234>我们对新想法的理解最初是浅层的，因为深入的理解需要更多的想法组成部分之间的联系，它只是需要更多的经验，因此需要更多的时间来发展以形成深刻的理解。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-017" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>017</span><div data-v-d5786234><p data-v-d5786234>经验可以帮助学生看到问题的深层结构，所以要通过大量的例子为学生提供经验</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-018" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>018</span><div data-v-d5786234><p data-v-d5786234>知识再浅也比没有知识要好得多，而浅表知识是通往深层知识的必经之路</p></div></blockquote><h2 id="第5章-反复练习值得吗" tabindex="-1" data-v-d5786234>第5章 反复练习值得吗？ <a class="header-anchor" href="#第5章-反复练习值得吗" aria-label="Permalink to “第5章 反复练习值得吗？”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-019" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>019</span><div data-v-d5786234><p data-v-d5786234>如果你做了足够多的代数练习，你将永远不会忘记它。</p></div></blockquote><aside class="reading-thought" aria-label="个人随想" data-v-d5786234><div class="reading-thought-meta" data-v-d5786234><span data-v-d5786234>我的随想</span><time datetime="2024-12-21" data-v-d5786234>2024/12/21</time></div><p data-v-d5786234>回想自己之前的学习方法（自主学习的部分）都是看完，听完，简单的记忆一下，就觉得自己学了，并没有复习，后面再遇到类似问题的时候，<br data-v-d5786234>感觉还是一个新问题，找到原因了。不断的去重复，看自己学习时记录的笔记。</p><blockquote class="reading-thought-source" data-v-d5786234><p class="reading-source-label" data-v-d5786234>对应原文</p><p data-v-d5786234>这种类型的复习被称为“超量学习”(overlearning)，即在你似乎知道一些事情之后继续学习</p></blockquote></aside><blockquote class="reading-excerpt" id="excerpt-020" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>020</span><div data-v-d5786234><p data-v-d5786234>这种类型的复习被称为“超量学习”(overlearning)，即在你似乎知道一些事情之后继续学习</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-021" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>021</span><div data-v-d5786234><p data-v-d5786234>深层结构也是如此。你可能在第一次看到深层结构时就理解了它，但这并不意味着你会在再次遇到它时就能自动识别出它。总之，练习有助于知识迁移，因为练习使深层结构更加明显</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-022" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>022</span><div data-v-d5786234><p data-v-d5786234>不仅要把练习分散到不同的时间，还要分散到不同的活动中</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-023" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>023</span><div data-v-d5786234><p data-v-d5786234>练习表层结构的各种形式有助于理解深层结构</p></div></blockquote><h2 id="第6章-让学生像真正的科学家、数学家和历史学家一样思考的秘诀是什么" tabindex="-1" data-v-d5786234>第6章 让学生像真正的科学家、数学家和历史学家一样思考的秘诀是什么？ <a class="header-anchor" href="#第6章-让学生像真正的科学家、数学家和历史学家一样思考的秘诀是什么" aria-label="Permalink to “第6章 让学生像真正的科学家、数学家和历史学家一样思考的秘诀是什么？”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-024" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>024</span><div data-v-d5786234><p data-v-d5786234>要想获得专业知识，达到专业水准，唯一的途径就是实践练习</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-025" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>025</span><div data-v-d5786234><p data-v-d5786234>根据标准智商测试，科学界的伟人并不以其非凡的才智而著称；可以肯定的是，他们非常聪明，但并不能与他们在各自领域所做出的杰出贡献成正比。他们真正的突出之处是他们持续工作的能力。伟大的科学家几乎都是工作狂。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-026" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>026</span><div data-v-d5786234><p data-v-d5786234>伟大的科学家有着惊人的毅力，他们的精神疲惫阈值非常高</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-027" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>027</span><div data-v-d5786234><p data-v-d5786234>达克沃思指出了两种基本的性格成分，即坚持和对长期目标的热情，并将其称为坚毅。</p></div></blockquote><aside class="reading-thought" aria-label="个人随想" data-v-d5786234><div class="reading-thought-meta" data-v-d5786234><span data-v-d5786234>我的随想</span><time datetime="2024-12-29" data-v-d5786234>2024/12/29</time></div><p data-v-d5786234>之前我觉得自己坚持学习的时间已经够长了，为什么还达不到自己想要的结果，现在看来自己只坚持了跟十年时间相比的非常非常非常短的一段时间，<br data-v-d5786234>说来惭愧，还是需要耐下心来，以更长时间为目标，慢慢走……</p><blockquote class="reading-thought-source" data-v-d5786234><p class="reading-source-label" data-v-d5786234>对应原文</p><p data-v-d5786234>坚持10年学习并没有什么神奇的，学习背景知识和发展我在本章中提到的自动化过程似乎需要很长时间</p></blockquote></aside><blockquote class="reading-excerpt" id="excerpt-028" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>028</span><div data-v-d5786234><p data-v-d5786234>坚持10年学习并没有什么神奇的，学习背景知识和发展我在本章中提到的自动化过程似乎需要很长时间。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-029" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>029</span><div data-v-d5786234><p data-v-d5786234>在大多数领域，10年是一个很好的经验法则。即使获得专家地位，学习和练习也不能结束，如果要继续保持地位，则需要继续努力练习</p></div></blockquote><aside class="reading-thought" aria-label="个人随想" data-v-d5786234><div class="reading-thought-meta" data-v-d5786234><span data-v-d5786234>我的随想</span><time datetime="2024-12-29" data-v-d5786234>2024/12/29</time></div><p data-v-d5786234>如果不能成为光，那就低下头，沐浴阳光</p><blockquote class="reading-thought-source" data-v-d5786234><p class="reading-source-label" data-v-d5786234>对应原文</p><p data-v-d5786234>对学生来说，一个更为谦虚和现实的目标是理解知识。学生可能不能发展自己的科学理论，但他们可以发展对现有理论的深刻理解。<br data-v-d5786234>一个学生可能不会依据史实给出全新的见解，但是她可以理解别人的诠释。</p></blockquote></aside><blockquote class="reading-excerpt" id="excerpt-030" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>030</span><div data-v-d5786234><p data-v-d5786234>对学生来说，一个更为谦虚和现实的目标是理解知识。学生可能不能发展自己的科学理论，但他们可以发展对现有理论的深刻理解。一个学生可能不会依据史实给出全新的见解，但是她可以理解别人的诠释。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-031" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>031</span><div data-v-d5786234><p data-v-d5786234>学生不能像专家一样创造并不意味着他们就不应该创造</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-032" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>032</span><div data-v-d5786234><p data-v-d5786234>初学作曲的学生还没有具备作曲的认知能力，但这并不意味着他们在作曲时不会感到开心，有时这个理由就足够了</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-033" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>033</span><div data-v-d5786234><p data-v-d5786234>最重要的是，让学生接受创造新事物的挑战往往难度很大，但这并不意味着永远回避这种任务。只要牢牢记住，学生能从中得到什么或者不能得到什么。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-034" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>034</span><div data-v-d5786234><p data-v-d5786234>即使是这个较为温和的目标，也需要在很长一段时间内进行大量的艰苦工作。但令人高兴的是，学习者可以看到进步的迹象，我认为这是长期保持动力的关键。不要过于关注雄心勃勃的目标本身，而要关注中途站，即成功的中间阶段。把“熟能生巧”换成“熟能进步”。</p></div></blockquote><h2 id="第8章-如何帮助-慢热型-学生" tabindex="-1" data-v-d5786234>第8章 如何帮助“慢热型”学生？ <a class="header-anchor" href="#第8章-如何帮助-慢热型-学生" aria-label="Permalink to “第8章 如何帮助“慢热型”学生？”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-035" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>035</span><div data-v-d5786234><p data-v-d5786234>成长型思维的干预集中在三种想法上：<br data-v-d5786234>- (1)努力尝试或寻求帮助并不意味着你很笨。<br data-v-d5786234>- (2)失败并不是因为能力低下，而是因为缺乏经验。<br data-v-d5786234>- (3)没有必要担心因为失败和暴露你不知道的东西而使你“看起来很笨”。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-036" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>036</span><div data-v-d5786234><p data-v-d5786234>唯一不犯错的人是那些从未做过任何事的人</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-037" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>037</span><div data-v-d5786234><p data-v-d5786234>大量的研究表明，最成功的减重方法并不是节食，而是日常生活方式的改变，人们相信自己在今后的每一天都能做到。</p></div></blockquote><h2 id="第9章-新技术能否改善学生的学习" tabindex="-1" data-v-d5786234>第9章 新技术能否改善学生的学习？ <a class="header-anchor" href="#第9章-新技术能否改善学生的学习" aria-label="Permalink to “第9章 新技术能否改善学生的学习？”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-038" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>038</span><div data-v-d5786234><p data-v-d5786234>指导原则有两层意思：一方面，它意味着技术改变了很多认知过程，但不一定是以你所预料的方式。另一方面，它还意味着一句你经常会听到的感叹：“技术已经改变了一切！”的确如此，但它并没有改变你思考的方式，也就是你思维运作的方式，而这正是我们开始探索的起点</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-039" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>039</span><div data-v-d5786234><p data-v-d5786234>对科技的适应来自你所处的环境，而不是你们这一代人</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-040" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>040</span><div data-v-d5786234><p data-v-d5786234>章的指导原则有两层意思：一方面，它意味着技术改变了很多认知过程，但不一定是以你所预料的方式。另一方面，它还意味着一句你经常会听到的感叹：“技术已经改变了一切！”的确如此，但它并没有改变你思考的方式，也就是你思维运作的方式，而这正是我们开始探索的起点</p></div></blockquote><h2 id="第10章-教师的大脑又是如何运作的" tabindex="-1" data-v-d5786234>第10章 教师的大脑又是如何运作的？ <a class="header-anchor" href="#第10章-教师的大脑又是如何运作的" aria-label="Permalink to “第10章 教师的大脑又是如何运作的？”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-041" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>041</span><div data-v-d5786234><p data-v-d5786234>刻意练习有以下特点：(1)挑选一个你自己不满意的技能的一个小特点，并试图改善它，设定一个具体的目标，而不是像“变得更好”这样一个模糊的愿望。(2)当你练习时，至少从和你一样了解该技能的人那里得到反馈。(3)把自己推到舒适区之外，尝试新的东西。(4)你会发现刻意练习在心智上要求很高，坦白来讲，它枯燥无趣。(5)你参与间接促进技能的活动。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-042" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>042</span><div data-v-d5786234><p data-v-d5786234>你描述你所看到的东西，除非有人问你，否则不要轻易建议他人应该采取何种不同的做法。你不想让人觉得你是个“无所不知”的家伙。如果你的搭档想知道你对如何解决某个问题的看法，她会询问你，在这种情况下，你当然应该竭尽所能提供你的任何想法。但是，在被问到这个问题之前，你要保持谨慎的、支持的观察态度，不要自动代入专家的角色，不管你对自己的解决方案有多自信。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-043" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>043</span><div data-v-d5786234><p data-v-d5786234>认知心理学<br data-v-d5786234>第二章<br data-v-d5786234>你的思考能力取决于你掌握的事实性知识<br data-v-d5786234>第三章<br data-v-d5786234>记忆是思考的残留物<br data-v-d5786234>产生记忆，需要做思考，去思考事物的意义<br data-v-d5786234>很有价值且有趣的知识并不一定为每个人所喜爱，而学生也应该不仅仅为了兴趣而学习，兴趣可以作为切入点。学生也需要学习与我无关的东西（与自己兴趣无关的东西，可能会让人觉得枯燥的东西）</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-044" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>044</span><div data-v-d5786234><p data-v-d5786234>第四章<br data-v-d5786234>我们在已有知识的背景下理解新事物，多数知识都是具体知识<br data-v-d5786234>- 要理解新事物可以将他们与我们已经理解的事物联系起来（类比）</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-045" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>045</span><div data-v-d5786234><p data-v-d5786234>第八章<br data-v-d5786234>智能是可以通过不断学习、练习来改变的，做有挑战性的工作 这是一件长久的事情，不是一蹴而就<br data-v-d5786234>失败并不可怕<br data-v-d5786234>成长型思维<br data-v-d5786234>成长型思维的干预集中在三种想法上：(1)努力尝试或寻求帮助并不意味着你很笨。(2)失败并不是因为能力低下，而是因为缺乏经验。(3)没有必要担心因为失败和暴露你不知道的东西而使你“看起来很笨”。<br data-v-d5786234>唯一不犯错的人是那些从未做过任何事的人<br data-v-d5786234>大量的研究表明，最成功的减重方法并不是节食，而是日常生活方式的改变，人们相信自己在今后的每一天都能做到。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-046" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>046</span><div data-v-d5786234><p data-v-d5786234>刻意练习有以下特点：(1)挑选一个你自己不满意的技能的一个小特点，并试图改善它，设定一个具体的目标，而不是像“变得更好”这样一个模糊的愿望。(2)当你练习时，至少从和你一样了解该技能的人那里得到反馈。(3)把自己推到舒适区之外，尝试新的东西。(4)你会发现刻意练习在心智上要求很高，坦白来讲，它枯燥无趣。(5)你参与间接促进技能的活动。</p></div></blockquote><h2 id="描述你所看到的东西-除非有人问你-否则不要轻易建议他人应该采取何种不同的做法" tabindex="-1" data-v-d5786234>描述你所看到的东西，除非有人问你，否则不要轻易建议他人应该采取何种不同的做法 <a class="header-anchor" href="#描述你所看到的东西-除非有人问你-否则不要轻易建议他人应该采取何种不同的做法" aria-label="Permalink to “描述你所看到的东西，除非有人问你，否则不要轻易建议他人应该采取何种不同的做法”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-047" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>047</span><div data-v-d5786234><p data-v-d5786234>你描述你所看到的东西，除非有人问你，否则不要轻易建议他人应该采取何种不同的做法。你不想让人觉得你是个“无所不知”的家伙。如果你的搭档想知道你对如何解决某个问题的看法，她会询问你，在这种情况下，你当然应该竭尽所能提供你的任何想法。但是，在被问到这个问题之前，你要保持谨慎的、支持的观察态度，不要自动代入专家的角色，不管你对自己的解决方案有多自信。</p></div></blockquote><h2 id="专家看待世界的方式与新手不同——他们看到的是深层结构-而不是表层结构——他们能这样看的关键原因是-他们在自己的领域有广泛而深刻的经验" tabindex="-1" data-v-d5786234>专家看待世界的方式与新手不同——他们看到的是深层结构，而不是表层结构——他们能这样看的关键原因是，他们在自己的领域有广泛而深刻的经验 <a class="header-anchor" href="#专家看待世界的方式与新手不同——他们看到的是深层结构-而不是表层结构——他们能这样看的关键原因是-他们在自己的领域有广泛而深刻的经验" aria-label="Permalink to “专家看待世界的方式与新手不同——他们看到的是深层结构，而不是表层结构——他们能这样看的关键原因是，他们在自己的领域有广泛而深刻的经验”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-048" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>048</span><div data-v-d5786234><p data-v-d5786234>你无须一口气做完所有的事情。期望在一两年之内变成“一代宗师”是不现实的。因为你不能一次性解决所有问题，你必须确定优先次序，决定最重要的事情，并专注于具体的、可管理的步骤，使你朝着目标前进。</p></div></blockquote><h2 id="查漏补缺-慢慢进步" tabindex="-1" data-v-d5786234>查漏补缺，慢慢进步 <a class="header-anchor" href="#查漏补缺-慢慢进步" aria-label="Permalink to “查漏补缺，慢慢进步”" data-v-d5786234>​</a></h2><blockquote class="reading-excerpt" id="excerpt-049" data-v-d5786234><span class="reading-excerpt-number" aria-hidden="true" data-v-d5786234>049</span><div data-v-d5786234><p data-v-d5786234>我曾经说过，刻意练习常常包括一些对目标技能没有直接帮助的活动，比如高尔夫球运动员练习举重和慢跑，以增强力量和耐力。如何将这一原则应用于教学？一个显著的例子是提高你的核心学科知识——如果你教历史，就多学点历史。如果你在小组内发言时仍然感到不自在，那就参加一个公共演讲课程。如果你对使用技术缺乏信心，那就找一些与你所在学校使用的工具有关的在线教程。但是我认为，这一原则的适用范围会远远超出最初的理解。<br data-v-d5786234>几年前，我遇到一位教师，她觉得自己在课堂上表现出色，但缺乏灵活性。她不能让自己偏离教学计划，即使她看到有机会发生真正有趣的事情。所以她参加了一个即兴戏剧班，以获得感受生活的勇气，在当下的生活中做出更多反应。她想让自己意识到，即便是抛开计划，结果依然不错。<br data-v-d5786234>如果你认为你创造的视觉辅助工具缺乏生机，那就学习一下平面设计吧。<br data-v-d5786234>如果你的背部因整日站立的时间过长而疼痛（或者腿部、脚部等其他部位），首先花钱买更舒适的鞋子，然后考虑练瑜伽。一些优质的网上瑜伽课程甚至可就是免费的。<br data-v-d5786234>如果你觉得你的课程计划枯燥乏味，需要瞬间的活力和热情，你可以借助舞台魔术的力量，给你的课堂创造并释放出悬念吧。<br data-v-d5786234>如果你喜欢把课程规划编排成故事（见第3章），但是你还没有理解透彻故事结构，那就上一门短篇小说的写作课程吧。<br data-v-d5786234>如果你想给学生更多的自主权，但仍然担心失控，那就研究领导力和如何赋予他人责任吧。<br data-v-d5786234>而且，我还认为我们每个人都应该学习认知心理学课程，当然要学了！</p></div></blockquote><footer class="reading-footer" data-v-d5786234><span data-v-d5786234>书籍来源：微信读书</span><span data-v-d5786234>整理时间：2025年</span></footer>',66))])])}const f=r(p,[["render",x],["__scopeId","data-v-d5786234"]]);export{_ as __pageData,f as default};
